#include <stdio.h>

int add(int a, int b) { return a + b; }
int multiply(int a, int b) { return a * b; }

int apply(int (*operation)(int, int), int x, int y) {
    return operation(x, y);
}

int main() {
    printf("add: %d\n", apply(add, 6, 7));
    printf("multiply: %d\n", apply(multiply, 6, 7));
    return 0;
}
